import base64, json, zlib

import frappe
from frappe.utils.nestedset import rebuild_tree


def execute():
	accounts = json.loads(zlib.decompress(base64.b64decode(DATA)))
	accounts.sort(key=lambda account: (account.get("parent_account") or "").count(" - "))
	for data in accounts:
		data = {key: value for key, value in data.items() if value is not None}
		name = data.pop("name")
		if not data.get("parent_account"):
			continue
		for key in ("name", "parent_account", "company"):
			if isinstance(data.get(key), str):
				data[key] = data[key].replace(" - ARB", " - APL")
		name = name.replace(" - ARB", " - APL")
		if frappe.db.exists("Account", name):
			continue
		doc = frappe.get_doc({"doctype": "Account", "name": name, **data})
		doc.flags.ignore_validate = True
		doc.db_insert()
	frappe.db.commit()
	rebuild_tree("Account", "parent_account")
	frappe.db.commit()


DATA = ''
